-- Core schema. Indexing tables (files, chunks, chunks_fts) arrive in Phase 6.
-- IDs are UUID text generated by the app; timestamps are ISO-8601 UTC text.

CREATE TABLE projects (
  id            TEXT PRIMARY KEY,
  name          TEXT NOT NULL,
  root_path     TEXT NOT NULL UNIQUE,
  settings_json TEXT NOT NULL DEFAULT '{}',
  created_at    TEXT NOT NULL
);

CREATE TABLE ideas (
  id                 TEXT PRIMARY KEY,
  title              TEXT NOT NULL,
  body               TEXT NOT NULL DEFAULT '',
  status             TEXT NOT NULL DEFAULT 'draft'
                     CHECK (status IN ('draft','evaluating','build','validate','hold','rejected')),
  reject_reason      TEXT,
  revisit_condition  TEXT,
  decided_session_id TEXT,
  created_at         TEXT NOT NULL,
  updated_at         TEXT NOT NULL
);
CREATE INDEX idx_ideas_status ON ideas(status);

CREATE TABLE sessions (
  id                TEXT PRIMARY KEY,
  project_id        TEXT REFERENCES projects(id) ON DELETE CASCADE,
  idea_id           TEXT REFERENCES ideas(id) ON DELETE SET NULL,
  type              TEXT NOT NULL CHECK (type IN ('new_idea','kill_idea','ask_project','audit','review_changes')),
  mode              TEXT NOT NULL CHECK (mode IN ('fast','balanced','deep')),
  status            TEXT NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending','running','completed','failed','cancelled')),
  config_json       TEXT NOT NULL DEFAULT '{}',
  final_report_json TEXT,
  est_cost          REAL,
  actual_cost       REAL NOT NULL DEFAULT 0,
  error             TEXT,
  created_at        TEXT NOT NULL,
  finished_at       TEXT
);
CREATE INDEX idx_sessions_project ON sessions(project_id, created_at);
CREATE INDEX idx_sessions_idea ON sessions(idea_id);

CREATE TABLE session_messages (
  id                 TEXT PRIMARY KEY,
  session_id         TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
  round              TEXT NOT NULL CHECK (round IN ('independent','critique','revision','judge','utility')),
  participant        TEXT NOT NULL,
  provider           TEXT NOT NULL,
  model              TEXT NOT NULL,
  role               TEXT,
  prompt_id          TEXT NOT NULL,
  prompt_version     INTEGER NOT NULL,
  request_files_json TEXT NOT NULL DEFAULT '[]',
  response_text      TEXT,
  response_json      TEXT,
  tokens_in          INTEGER NOT NULL DEFAULT 0,
  tokens_out         INTEGER NOT NULL DEFAULT 0,
  cached_tokens      INTEGER NOT NULL DEFAULT 0,
  cost               REAL NOT NULL DEFAULT 0,
  latency_ms         INTEGER,
  error              TEXT,
  created_at         TEXT NOT NULL
);
CREATE INDEX idx_messages_session ON session_messages(session_id, created_at);

CREATE TABLE decisions (
  id            TEXT PRIMARY KEY,
  project_id    TEXT REFERENCES projects(id) ON DELETE CASCADE,
  idea_id       TEXT REFERENCES ideas(id) ON DELETE SET NULL,
  session_id    TEXT REFERENCES sessions(id) ON DELETE SET NULL,
  title         TEXT NOT NULL,
  reason        TEXT NOT NULL DEFAULT '',
  user_approved INTEGER NOT NULL DEFAULT 0 CHECK (user_approved IN (0,1)),
  decided_at    TEXT NOT NULL
);
CREATE INDEX idx_decisions_project ON decisions(project_id, decided_at);

CREATE TABLE findings (
  id            TEXT PRIMARY KEY,
  project_id    TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  session_id    TEXT REFERENCES sessions(id) ON DELETE SET NULL,
  title         TEXT NOT NULL,
  description   TEXT NOT NULL DEFAULT '',
  category      TEXT NOT NULL,
  severity      TEXT NOT NULL CHECK (severity IN ('critical','high','medium','low','info')),
  confidence    TEXT NOT NULL CHECK (confidence IN ('confirmed','high','possible','speculative')),
  verification  TEXT NOT NULL DEFAULT 'unverified' CHECK (verification IN ('verified','unverified')),
  impact        INTEGER, risk INTEGER, urgency INTEGER, effort INTEGER,
  priority      TEXT CHECK (priority IN ('P0','P1','P2','P3')),
  suggested_fix TEXT,
  status        TEXT NOT NULL DEFAULT 'open'
                CHECK (status IN ('open','accepted','wontfix','done','false_positive')),
  fingerprint   TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  last_seen_at  TEXT NOT NULL,
  UNIQUE (project_id, fingerprint)
);

CREATE TABLE finding_evidence (
  id         TEXT PRIMARY KEY,
  finding_id TEXT NOT NULL REFERENCES findings(id) ON DELETE CASCADE,
  file_path  TEXT NOT NULL,
  start_line INTEGER,
  end_line   INTEGER,
  quote      TEXT,
  verified   INTEGER NOT NULL DEFAULT 0 CHECK (verified IN (0,1))
);

CREATE TABLE brain_facts (
  id                TEXT PRIMARY KEY,
  project_id        TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  section           TEXT NOT NULL,
  statement         TEXT NOT NULL,
  source            TEXT NOT NULL CHECK (source IN ('observed','inferred','user_confirmed')),
  evidence_json     TEXT NOT NULL DEFAULT '[]',
  origin_session_id TEXT REFERENCES sessions(id) ON DELETE SET NULL,
  status            TEXT NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending','active','superseded','rejected')),
  updated_at        TEXT NOT NULL
);
CREATE INDEX idx_brain_project ON brain_facts(project_id, section);

-- API keys are never stored here (OS keychain only, ADR-0004).
CREATE TABLE provider_configs (
  provider      TEXT PRIMARY KEY,
  enabled       INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0,1)),
  default_model TEXT,
  temperature   REAL,
  max_tokens    INTEGER,
  base_url      TEXT
);

CREATE TABLE model_prices (
  provider        TEXT NOT NULL,
  model           TEXT NOT NULL,
  in_per_mtok     REAL NOT NULL,
  out_per_mtok    REAL NOT NULL,
  cached_per_mtok REAL,
  PRIMARY KEY (provider, model)
);
